function Keys($list){$seen=@{};$keys=@();foreach($e in $list){$n=$seen[$e.Name];if($null -eq $n){$n=0};$seen[$e.Name]=$n+1;$keys+=($e.Name+'#'+$n)};return ,$keys}
$changes=@();$listReport=@();$baseDifferences=@()
foreach($sec in @('Models','Events','Regions','Parts','Routes')){foreach($prop in $b.$sec.PSObject.Properties){if($prop.Value -isnot [Collections.IList]){continue};$sub=$prop.Name;$dl=$d.$sec.$sub;$cl=$c.$sec.$sub;$bl=$b.$sec.$sub;$dk=Keys $dl;$ck=Keys $cl;$bk=Keys $bl;$dm=@{};for($n=0;$n -lt $dk.Count;$n++){$dm[$dk[$n]]=$n};$cm=@{};for($n=0;$n -lt $ck.Count;$n++){$cm[$ck[$n]]=$n};$bm=@{};for($n=0;$n -lt $bk.Count;$n++){$bm[$bk[$n]]=$n};$listReport+=@{section=$sec;list=$sub;clean=$cl.Count;donor=$dl.Count;dojo=$bl.Count};for($n=0;$n -lt $bl.Count;$n++){$key=$bk[$n];if(-not $dm.ContainsKey($key)){Need (-not $cm.ContainsKey($key)) "New map entry collision $sec/$sub/$key";$changes+=@{section=$sec;list=$sub;index=$n;new=$true;name=$bl[$n].Name};continue};$dn=$dm[$key];if((Canon $bl[$n]) -cne (Canon $dl[$dn])){Need ($cm.ContainsKey($key)) "Modified source entry missing in clean map $sec/$sub/$key";$cn=$cm[$key];$changes+=@{section=$sec;list=$sub;index=$n;cleanIndex=$cn;new=$false;name=$bl[$n].Name;cleanMatchesDonor=((Canon $cl[$cn]) -ceq (Canon $dl[$dn]))}}};foreach($key in $dk){Need ($bm.ContainsKey($key)) "Dojo deletes source entry $sec/$sub/$key";if(-not $cm.ContainsKey($key)){$baseDifferences+=@{section=$sec;list=$sub;key=$key;onlyInDonor=$true}}}}}
Json-Write @{lists=$listReport;changes=$changes;baseDifferences=$baseDifferences;note='Compare duplicate names by per-type ordinal. Ignore serialized Index/Indices fields recomputed by SoulsFormats writer from names.'} (Join-Path $taskRoot 'reports\MAP_SEMANTIC_DELTA.json')
$mods=Join-Path $taskRoot 'build\mods';foreach($change in $changes){$sec=$change.section;$sub=$change.list;$n=$change.index;if($change.new){$c.$sec.$sub.Add($b.$sec.$sub[$n].DeepCopy())}else{Need $change.cleanMatchesDonor "Conflict modifying original map entry $sec/$sub/$n";$c.$sec.$sub[$change.cleanIndex]=$b.$sec.$sub[$n].DeepCopy()}}
